from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import ColorSensor, Motor, UltrasonicSensor
from pybricks.robotics import Car

# Set up all devices.
prime_hub = PrimeHub()
color_sensor = ColorSensor(Port.F)
distance_sensor_right = UltrasonicSensor(Port.A)
distance_sensor_left = UltrasonicSensor(Port.B)
distance_sensor_front = UltrasonicSensor(Port.E)
car = Car(steering, driveshaft)
driveshaft = Motor(Port.C, Direction.CLOCKWISE)
steering = Motor(Port.D, Direction.CLOCKWISE)




# The main program starts here.
car.drive_power(100)
steering.reset_angle(0)
